// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref) public {
        vm.assume(caller != address(0) && ref != address(0) && caller != ref);
        // Seed the market so collectDrugs can be called
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);
        // Give the caller some drugs via buyDrugs
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.buyDrugs{value: 0.1 ether}();
        // Record block.timestamp before the call
        uint256 timeBefore = block.timestamp;
        // Perform collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);
        // The rule: lastCollect[caller] must equal the current block.timestamp after the call
        assertTrue(c.lastCollect(caller) == block.timestamp);
    }
}

